import { readFileSync } from 'node:fs';
import { expect, it } from 'vitest';
import { captureAutoBasis, executeAutoBirth, finishAutoCapture } from '@/tools/video-editor/commands/autoCapture.ts';

// Generate with export.py against the explicit frozen Agent archive. No embedded
// candidate hashes, handoff fixtures, trimmed rows or expected records generated by App.
const vectors = JSON.parse(readFileSync(process.env.AUTO_NATIVE_VECTORS!, 'utf8'));
for (const vector of vectors) {
  it(vector.name + (vector.refusal ? ' refuses with native' : ' exactly matches native'), () => {
    const before = structuredClone(vector.bundle);
    const run = () => vector.command
      ? executeAutoBirth(vector.bundle, vector.command, vector.verified)
      : finishAutoCapture(captureAutoBasis(vector.bundle, vector.approval), vector.media, vector.verified);
    if (vector.refusal) expect(run).toThrow();
    else {
      expect(run()).toEqual(vector.expected);
      if (!vector.command) {
        const basis = captureAutoBasis(vector.bundle, vector.approval);
        expect(Object.isFrozen(basis.bundle)).toBe(true);
        expect(run()).toEqual(finishAutoCapture(JSON.parse(JSON.stringify(basis)), vector.media, vector.verified));
        expect(vector.expected.bundle.parent).toEqual(vector.bundle.parent);
        const sibling = vector.bundle.placements[1].shot_id;
        expect(vector.expected.bundle.shots[sibling]).toEqual(vector.bundle.shots[sibling]);
      }
    }
    expect(vector.bundle).toEqual(before);
  });
}

it('refuses incomplete approval and exact media contract shapes', () => {
  const vector = vectors[0];
  for (const field of ['autoApprove', 'owner', 'ownership', 'clipId', 'mode', 'anchor', 'preferredTrack', 'fallbackAt', 'fallbackTrack']) {
    const approval = structuredClone(vector.approval);
    delete approval[field];
    expect(() => captureAutoBasis(vector.bundle, approval), field).toThrow();
  }
  const basis = captureAutoBasis(vector.bundle, vector.approval);
  for (const field of Object.keys(vector.media)) {
    const media = structuredClone(vector.media);
    delete media[field];
    expect(() => finishAutoCapture(basis, media, { ...vector.verified, selection: media }), field).toThrow();
  }
});
